'use client';

import { useState } from 'react';
import { motion } from 'framer-motion';

// ─── Data ─────────────────────────────────────────────────────────────────────

interface GalleryItem {
  id     : number;
  /** Real src once photos exist, empty string = show placeholder */
  src    : string;
  alt    : string;
  caption: string;
  /** Controls CSS grid span */
  span   : 'normal' | 'tall' | 'wide';
}

/**
 * Replace `src` values with your actual pre-wedding photo paths
 * (e.g. '/photos/pre-wed-01.jpg') when they are ready.
 */
const ITEMS: GalleryItem[] = [
  { id: 1,  src: '', alt: 'Adli & Rima — Tepian Senja',      caption: 'Berdua di Tepian Senja',    span: 'tall'   },
  { id: 2,  src: '', alt: 'Adli & Rima — Kebun Teh',         caption: 'Di Antara Hijau Abadi',     span: 'normal' },
  { id: 3,  src: '', alt: 'Adli & Rima — Detail Batik',      caption: 'Warisan Nusantara',          span: 'normal' },
  { id: 4,  src: '', alt: 'Adli & Rima — Candi',             caption: 'Dua Jiwa, Satu Candi',      span: 'wide'   },
  { id: 5,  src: '', alt: 'Adli & Rima — Sawah',             caption: 'Di Lembah Padi',            span: 'normal' },
  { id: 6,  src: '', alt: 'Adli & Rima — Indoor',            caption: 'Senyum Pertama',            span: 'tall'   },
  { id: 7,  src: '', alt: 'Adli & Rima — Outdoor',           caption: 'Perjalanan Dimulai',        span: 'normal' },
  { id: 8,  src: '', alt: 'Adli & Rima — Close-up',          caption: 'Cinta Dalam Detail',        span: 'wide'   },
  { id: 9,  src: '', alt: 'Adli & Rima — Golden Hour',       caption: 'Cahaya Sore yang Abadi',    span: 'normal' },
  { id: 10, src: '', alt: 'Adli & Rima — Formal Portrait',   caption: 'Potret Pengantin Sogan',    span: 'normal' },
];

// Stable gradient per placeholder so the grid looks intentionally varied
const PLACEHOLDER_GRADIENTS = [
  'from-slate-900 via-amber-950/40 to-slate-800',
  'from-amber-950/60 via-slate-900 to-slate-800',
  'from-slate-800 via-slate-900 to-amber-950/30',
  'from-amber-900/30 via-slate-900 to-slate-900',
];

// Grid span classes
const SPAN_CLASSES: Record<GalleryItem['span'], string> = {
  normal : '',
  tall   : 'row-span-2',
  wide   : 'col-span-2',
};

// ─── Parang-inspired SVG motif ────────────────────────────────────────────────

function SoganMotif({ className = '' }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 80 80"
      className={className}
      fill="none"
      aria-hidden
    >
      <path
        d="M40 8 C56 24, 72 42, 40 72 C8 42, 24 24, 40 8 Z"
        stroke="currentColor"
        strokeWidth="1.2"
        opacity=".6"
      />
      <path
        d="M40 18 C53 31, 64 44, 40 64 C16 44, 27 31, 40 18 Z"
        stroke="currentColor"
        strokeWidth="0.7"
        strokeDasharray="3 2.5"
        opacity=".4"
      />
      <circle cx="40" cy="40" r="4" fill="currentColor" opacity=".35" />
      <circle cx="40" cy="22" r="2" fill="currentColor" opacity=".25" />
    </svg>
  );
}

// ─── Single gallery card ──────────────────────────────────────────────────────

function GalleryCard({ item, index }: { item: GalleryItem; index: number }) {
  const [loaded, setLoaded] = useState(false);
  const hasImage = item.src.length > 0;

  return (
    <motion.article
      className={`
        relative group overflow-hidden rounded-2xl cursor-default
        ${SPAN_CLASSES[item.span]}
      `}
      style={{
        background   : 'rgba(15,23,42,0.55)',
        border       : '1px solid rgba(245,158,11,0.12)',
        backdropFilter: 'blur(10px)',
        minHeight    : '10rem',
      }}
      initial={{ opacity: 0, y: 28, scale: 0.97 }}
      whileInView={{ opacity: 1, y: 0, scale: 1 }}
      viewport={{ once: true, margin: '-40px' }}
      transition={{ duration: 0.55, delay: index * 0.07, ease: 'easeOut' }}
      whileHover={{ y: -5, transition: { duration: 0.25 } }}
    >
      {/* ── Real image ── */}
      {hasImage && (
        <img
          src={item.src}
          alt={item.alt}
          onLoad={() => setLoaded(true)}
          className={`
            absolute inset-0 w-full h-full object-cover
            transition-transform duration-700 group-hover:scale-108
            ${loaded ? 'opacity-100' : 'opacity-0'}
          `}
        />
      )}

      {/* ── Placeholder (shown while image loading or no src) ── */}
      {(!hasImage || !loaded) && (
        <div
          className={`absolute inset-0 bg-gradient-to-br ${
            PLACEHOLDER_GRADIENTS[item.id % PLACEHOLDER_GRADIENTS.length]
          } flex items-center justify-center`}
        >
          <SoganMotif className="w-14 h-14 text-amber-700/40 group-hover:scale-110 transition-transform duration-700" />

          {/* Corner filigree */}
          {[
            'top-2    left-2  border-t border-l',
            'top-2    right-2 border-t border-r',
            'bottom-2 left-2  border-b border-l',
            'bottom-2 right-2 border-b border-r',
          ].map(cls => (
            <div
              key={cls}
              className={`absolute w-4 h-4 border-amber-800/30 ${cls}`}
            />
          ))}

          {/* Coming soon label */}
          <span
            className="absolute bottom-2 inset-x-0 text-center text-[9px] tracking-[0.32em] uppercase text-amber-800/35"
            style={{ fontFamily: "'EB Garamond', serif" }}
          >
            Segera
          </span>
        </div>
      )}

      {/* ── Hover caption overlay ── */}
      <div className="absolute inset-0 flex items-end p-4 opacity-0 group-hover:opacity-100 transition-opacity duration-400"
           style={{ background: 'linear-gradient(to top, rgba(2,6,23,0.78) 0%, transparent 60%)' }}>
        <p
          className="text-amber-100/90 text-xs leading-relaxed translate-y-2 group-hover:translate-y-0 transition-transform duration-300"
          style={{ fontFamily: "'Cormorant Garamond', serif" }}
        >
          {item.caption}
        </p>
      </div>

      {/* Border glow on hover */}
      <div
        className="absolute inset-0 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-400 pointer-events-none"
        style={{ boxShadow: 'inset 0 0 0 1px rgba(245,158,11,0.22)' }}
        aria-hidden
      />
    </motion.article>
  );
}

// ─── Section header ───────────────────────────────────────────────────────────

function Header() {
  return (
    <motion.div
      className="flex flex-col items-center gap-3 text-center"
      initial={{ opacity: 0, y: 26 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.7 }}
    >
      <svg viewBox="0 0 128 18" className="w-32 text-amber-700/50" fill="none" aria-hidden>
        <path d="M0 9 Q32 2 64 9 Q96 16 128 9" stroke="currentColor" strokeWidth="1" strokeDasharray="4 3" />
        <circle cx="64" cy="9" r="2.5" fill="currentColor" />
        <circle cx="48" cy="9" r="1.5" fill="currentColor" opacity=".55" />
        <circle cx="80" cy="9" r="1.5" fill="currentColor" opacity=".55" />
      </svg>

      <p
        className="text-[11px] tracking-[0.42em] uppercase text-amber-600/65"
        style={{ fontFamily: "'EB Garamond', serif" }}
      >
        Cerita Sebelum Hari Itu
      </p>

      <h2
        className="text-3xl sm:text-4xl font-light"
        style={{
          fontFamily: "'Cinzel', serif",
          background: 'linear-gradient(135deg, #fbbf24 0%, #92400e 50%, #fbbf24 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor : 'transparent',
          backgroundClip      : 'text',
        }}
      >
        Galeri Pra-Nikah
      </h2>

      <p
        className="text-sm text-slate-400 max-w-[260px] leading-relaxed"
        style={{ fontFamily: "'Cormorant Garamond', serif" }}
      >
        Setiap gambar menyimpan sepotong cerita dari perjalanan kami menuju altar
      </p>

      <div className="flex items-center gap-3 w-44">
        <div className="h-px flex-1" style={{ background: 'linear-gradient(to right, transparent, rgba(180,83,9,0.45))' }} />
        <span className="text-amber-600/50 text-xs">✦</span>
        <div className="h-px flex-1" style={{ background: 'linear-gradient(to left, transparent, rgba(180,83,9,0.45))' }} />
      </div>
    </motion.div>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

export default function Gallery() {
  return (
    <section className="w-full py-20 px-4 sm:px-6 flex flex-col items-center gap-12 relative overflow-hidden">

      {/* Ambient glows */}
      <div className="absolute inset-0 pointer-events-none" aria-hidden>
        <div style={{
          position: 'absolute', top: '10%', right: '-4rem',
          width: '18rem', height: '18rem', borderRadius: '9999px',
          background: 'radial-gradient(circle, rgba(120,53,15,0.07), transparent 70%)',
        }} />
        <div style={{
          position: 'absolute', bottom: '10%', left: '-4rem',
          width: '18rem', height: '18rem', borderRadius: '9999px',
          background: 'radial-gradient(circle, rgba(120,53,15,0.07), transparent 70%)',
        }} />
      </div>

      <Header />

      {/* ── Masonry-style CSS grid ── */}
      {/*
        Layout:
          mobile  → 2 columns, auto-rows 160 px
          sm+     → 3 columns, auto-rows 180 px
        span="tall"  → row-span-2  (portrait feel)
        span="wide"  → col-span-2  (landscape feel)
        span="normal"→ 1×1
      */}
      <div
        className="w-full max-w-4xl grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-4 relative z-10"
        style={{ gridAutoRows: 'clamp(140px, 20vw, 180px)' }}
      >
        {ITEMS.map((item, idx) => (
          <GalleryCard key={item.id} item={item} index={idx} />
        ))}
      </div>

      {/* Closing quote */}
      <motion.blockquote
        className="text-center max-w-sm relative z-10"
        initial={{ opacity: 0, y: 16 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.7, delay: 0.25 }}
      >
        <p
          className="text-sm text-slate-500 italic leading-relaxed"
          style={{ fontFamily: "'Cormorant Garamond', serif" }}
        >
          &ldquo;Seperti batik Sogan yang tumbuh dari akar bumi Jawa,
          cinta kami terpatri dalam setiap lembar kehidupan.&rdquo;
        </p>
        <footer
          className="mt-3 text-[11px] tracking-[0.32em] uppercase text-amber-800/45"
          style={{ fontFamily: "'EB Garamond', serif" }}
        >
          — Adli &amp; Rima
        </footer>
      </motion.blockquote>
    </section>
  );
}
