// ─── Page root ────────────────────────────────────────────────────────────────

export default function Home() {
  const [isOpened,   setIsOpened]   = useState(false);
  const [guestName,  setGuestName]  = useState('Tamu Undangan');

  return (
    <main className="relative h-screen w-full overflow-hidden bg-[#0B1528] text-white">

      {/* Read ?to= param — wrapped in Suspense because useSearchParams() requires it */}
      <Suspense fallback={null}>
        <GuestNameReader onName={setGuestName} />
      </Suspense>

      {/* ── Cover (exits with zoom-through) ── */}
      <AnimatePresence>
        {!isOpened && (
          <CoverPage
            key="cover"
            guestName={guestName}
            onOpen={() => setIsOpened(true)}
          />
        )}
      </AnimatePresence>

      {/* ── Main scrollable content (always mounted, invisible while cover shown) ── */}
      <AnimatePresence>
        {isOpened && (
          <motion.div
            key="content"
            className="absolute inset-0"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay: 0.3 }}
          >
            <MainContent guestName={guestName} />
          </motion.div>
        )}
      </AnimatePresence>
    </main>
  );
}